CREATE TABLE agents_platform.mcp_oauth_clients (id text PRIMARY KEY, name text NOT NULL, redirect_uris text[] NOT NULL, registration_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agents_platform.mcp_oauth_requests (hash text PRIMARY KEY, client_id text NOT NULL REFERENCES agents_platform.mcp_oauth_clients(id), redirect_uri text NOT NULL, resource text NOT NULL, scopes text[] NOT NULL, state text NOT NULL, challenge text NOT NULL, account_id uuid REFERENCES agents_platform.accounts(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE agents_platform.mcp_oauth_codes (hash text PRIMARY KEY, client_id text NOT NULL REFERENCES agents_platform.mcp_oauth_clients(id), account_id uuid NOT NULL REFERENCES agents_platform.accounts(id), organization_id uuid NOT NULL REFERENCES agents_platform.organizations(id), redirect_uri text NOT NULL, resource text NOT NULL, scopes text[] NOT NULL, challenge text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE agents_platform.mcp_oauth_connections (id uuid PRIMARY KEY, client_id text NOT NULL REFERENCES agents_platform.mcp_oauth_clients(id), account_id uuid NOT NULL REFERENCES agents_platform.accounts(id), organization_id uuid NOT NULL REFERENCES agents_platform.organizations(id), resource text NOT NULL, scopes text[] NOT NULL, access_hash text NOT NULL UNIQUE, access_expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz);
CREATE TABLE agents_platform.mcp_oauth_refresh (hash text PRIMARY KEY, connection_id uuid NOT NULL REFERENCES agents_platform.mcp_oauth_connections(id), expires_at timestamptz NOT NULL, used_at timestamptz);
